// Generated from src/registry/sources/control-ui/recipes/resizable.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const resizableKnobs = [
  "--cui-resizable-group-background",
  "--cui-resizable-group-radius",
  "--cui-resizable-group-border-color",
  "--cui-resizable-handle-color",
  "--cui-resizable-handle-hover-background",
  "--cui-resizable-handle-active-background",
  "--cui-resizable-grip-radius",
  "--cui-resizable-grip-background",
  "--cui-resizable-grip-foreground",
] as const;
export type ResizableKnobStyle = Partial<Record<(typeof resizableKnobs)[number], string>>;

@layer components {
  :where([data-control-family="resizable"][data-slot="panel-group"]) {
    --cui-resizable-group-background: var(--card);
    --cui-resizable-group-radius: var(--radius-panel);
    --cui-resizable-group-border-color: var(--border);
    --cui-resizable-handle-color: var(--foreground);
    --cui-resizable-handle-hover-background: oklch(from var(--foreground) l c h / 0.25);
    --cui-resizable-handle-active-background: oklch(from var(--foreground) l c h / 0.4);
    --cui-resizable-grip-radius: var(--radius-control);
    --cui-resizable-grip-background: var(--card);
    --cui-resizable-grip-foreground: var(--muted-foreground);
    background-color: var(--cui-resizable-group-background);
    color: var(--card-foreground);
  }

  :where([data-control-family="resizable"][data-slot="panel-group"][data-variant="framed"]) {
    border: 1px solid var(--cui-resizable-group-border-color);
    border-radius: var(--cui-resizable-group-radius);
    box-shadow: var(--shadow-sm);
  }

  :where([data-control-family="resizable"][data-slot="panel-group"][data-variant="nested"]) {
    --cui-resizable-group-background: transparent;
    --cui-resizable-group-radius: 0px;
  }

  :where([data-control-family="resizable"][data-slot="handle"]) {
    --_resizable-gradient-color: var(--cui-resizable-handle-color);
    transition-property: background-color, box-shadow, opacity;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
    outline-style: none;
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="solid"]) {
    background-color: var(--border);
  }

  :where(
    [data-control-family="resizable"][data-slot="handle"][data-variant="solid"][data-separator="hover"],
    [data-control-family="resizable"][data-slot="handle"][data-variant="solid"][data-separator="focus"]
  ) {
    background-color: var(--cui-resizable-handle-hover-background);
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="solid"][data-separator="active"]) {
    background-color: var(--cui-resizable-handle-active-background);
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-separator="focus"]) {
    box-shadow: 0 0 0 2px oklch(from var(--foreground) l c h / 0.2);
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-separator="disabled"]) {
    opacity: 0.5;
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="hover"])::before {
    position: absolute;
    inset: 0;
    content: "";
    opacity: 0;
    transition-property: opacity;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="hover"][data-axis="vertical"])::before {
    background-image: linear-gradient(to bottom, var(--_resizable-gradient-color), oklch(from var(--_resizable-gradient-color) l c h / 0));
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="hover"][data-axis="horizontal"])::before {
    background-image: linear-gradient(to right, var(--_resizable-gradient-color), oklch(from var(--_resizable-gradient-color) l c h / 0));
  }

  :where(
    [data-control-family="resizable"][data-slot="handle"][data-variant="hover"]:is(
      [data-separator="hover"],
      [data-separator="focus"],
      [data-separator="active"]
    )
  )::before {
    opacity: 1;
  }

  :where([data-control-family="resizable"][data-slot="handle-grip"]) {
    border: 1px solid var(--border);
    border-radius: var(--cui-resizable-grip-radius);
    background-color: var(--cui-resizable-grip-background);
    color: var(--cui-resizable-grip-foreground);
    box-shadow: var(--shadow-sm);
    opacity: 1;
    transition-property: opacity;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="resizable"][data-slot="handle-grip"][data-variant="hover"]) {
    opacity: 0;
  }

  :where(
    [data-control-family="resizable"][data-slot="handle"]:is([data-separator="hover"], [data-separator="focus"], [data-separator="active"])
      > [data-slot="handle-grip"][data-variant="hover"]
  ) {
    opacity: 1;
  }
}

